"""tool.py - Find and remove duplicate files safely."""

import argparse
import hashlib
import logging
from pathlib import Path
import sys


def setup_logger(verbose: bool) -> logging.Logger:
    level = logging.DEBUG if verbose else logging.INFO
    logging.basicConfig(
        level=level,
        format="%(asctime)s [%(levelname)s] %(message)s",
        datefmt="%H:%M:%S",
    )
    return logging.getLogger("dedup")


def hash_file(path: Path, chunk_size: int = 65536) -> str:
    """Calculate SHA-256 hash in chunks to handle large files safely."""
    hasher = hashlib.sha256()
    with open(path, "rb") as f:
        while chunk := f.read(chunk_size):
            hasher.update(chunk)
    return hasher.hexdigest()


def find_and_purge_duplicates(
    target_dir: Path,
    dry_run: bool = True,
    logger: logging.Logger = None,
) -> tuple[int, int]:
    """Scans target_dir and deletes duplicate files by content hash."""
    if not target_dir.exists() or not target_dir.is_dir():
        raise ValueError(f"Target directory does not exist: {target_dir}")

    seen_hashes: dict[str, Path] = {}
    dupes_count = 0
    bytes_freed = 0

    # Group candidate files by size first to skip unnecessary hashing
    size_map: dict[int, list[Path]] = {}
    for p in target_dir.rglob("*"):
        if p.is_file() and not p.is_symlink():
            try:
                sz = p.stat().st_size
                size_map.setdefault(sz, []).append(p)
            except OSError as err:
                logger.warning(f"Could not stat {p}: {err}")

    # Only hash files that share the exact same byte size
    for size, paths in size_map.items():
        if len(paths) < 2:
            continue

        for p in paths:
            try:
                file_hash = hash_file(p)
            except OSError as err:
                logger.warning(f"Could not read {p}: {err}")
                continue

            if file_hash in seen_hashes:
                dupes_count += 1
                bytes_freed += size
                original = seen_hashes[file_hash]
                if dry_run:
                    logger.info(f"[DRY-RUN] Would delete: {p} (matches {original.name})")
                else:
                    try:
                        p.unlink()
                        logger.info(f"Deleted duplicate: {p} (matches {original.name})")
                    except OSError as err:
                        logger.error(f"Failed to delete {p}: {err}")
            else:
                seen_hashes[file_hash] = p

    return dupes_count, bytes_freed


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Find and remove duplicate files safely by hash."
    )
    parser.add_argument(
        "--dir",
        type=Path,
        default=Path("."),
        help="Directory to scan for duplicates (default: current directory)",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        default=False,
        help="Simulate cleanup without deleting any files",
    )
    parser.add_argument(
        "--verbose",
        "-v",
        action="store_true",
        help="Enable detailed debug logging",
    )

    args = parser.parse_args()
    logger = setup_logger(args.verbose)

    if args.dry_run:
        logger.info("Running in DRY-RUN mode. No files will be modified or removed.")
    else:
        logger.warning("LIVE RUN: Duplicate files will be permanently deleted.")

    try:
        count, freed = find_and_purge_duplicates(
            target_dir=args.dir,
            dry_run=args.dry_run,
            logger=logger,
        )
        mb = freed / (1024 * 1024)
        logger.info(f"Scan complete. Found {count} duplicates ({mb:.2f} MB reclaimable).")
    except Exception as exc:
        logger.error(f"Fatal error during execution: {exc}")
        sys.exit(1)


if __name__ == "__main__":
    main()
